-- WV-3: immutable, explicit continuation decisions for expiring maintenance assignments.
alter table public.wartungsvertrag_zuordnungen
  add column if not exists vorgaenger_zuordnung_id bigint null references public.wartungsvertrag_zuordnungen(id) on delete restrict;

alter table public.wartungsvertrag_zuordnungen
  drop constraint if exists ck_wvz_vorgaenger_not_self;
alter table public.wartungsvertrag_zuordnungen
  add constraint ck_wvz_vorgaenger_not_self check (vorgaenger_zuordnung_id is null or vorgaenger_zuordnung_id <> id);
create unique index if not exists ux_wvz_vorgaenger_eindeutig on public.wartungsvertrag_zuordnungen(vorgaenger_zuordnung_id) where vorgaenger_zuordnung_id is not null;
create index if not exists ix_wvz_hauptmitglied_gueltig_bis on public.wartungsvertrag_zuordnungen(hauptmitglied_id, gueltig_bis) where gueltig_bis is not null;

create table if not exists public.wartungsvertrag_folgeentscheidung (
  id bigint generated by default as identity primary key,
  vorgaenger_zuordnung_id bigint not null references public.wartungsvertrag_zuordnungen(id) on delete restrict,
  entscheidung text not null check (entscheidung in ('verlaengern','nicht_verlaengern')),
  entscheidungsdatum date not null,
  entschieden_am timestamptz not null default now(),
  entschieden_von_auth_user_id uuid not null references auth.users(id) on delete restrict,
  vorstandsbeschlussdatum date null,
  initiator text null check (initiator in ('verein','mitglied','beidseitig')),
  begruendung text null,
  folgezuordnung_id bigint null unique references public.wartungsvertrag_zuordnungen(id) on delete restrict,
  kommunikationsvorgang_id bigint null unique references public.kommunikationsvorgang(id) on delete restrict,
  zurueckgenommen_am timestamptz null,
  zurueckgenommen_von_auth_user_id uuid null references auth.users(id) on delete restrict,
  ruecknahmebegruendung text null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  constraint ck_wvfe_fachlogik check (
    (entscheidung='verlaengern' and folgezuordnung_id is not null and vorstandsbeschlussdatum is not null and initiator is null and zurueckgenommen_am is null and zurueckgenommen_von_auth_user_id is null)
    or (entscheidung='nicht_verlaengern' and folgezuordnung_id is null and initiator is not null)
  ),
  constraint ck_wvfe_ruecknahme check ((zurueckgenommen_am is null and zurueckgenommen_von_auth_user_id is null and ruecknahmebegruendung is null) or (entscheidung='nicht_verlaengern' and zurueckgenommen_am is not null and zurueckgenommen_von_auth_user_id is not null))
);
create unique index if not exists ux_wvfe_wirksam_je_vorgaenger on public.wartungsvertrag_folgeentscheidung(vorgaenger_zuordnung_id) where zurueckgenommen_am is null;
create index if not exists ix_wvfe_vorgaenger on public.wartungsvertrag_folgeentscheidung(vorgaenger_zuordnung_id);

alter table public.wartungsvertrag_dokument_workflow add column if not exists workflow_art text not null default 'erstvertrag';
alter table public.wartungsvertrag_dokument_workflow add column if not exists folgeentscheidung_id bigint null references public.wartungsvertrag_folgeentscheidung(id) on delete restrict;
alter table public.wartungsvertrag_dokument_workflow drop constraint if exists ck_wvdw_workflow_art;
alter table public.wartungsvertrag_dokument_workflow add constraint ck_wvdw_workflow_art check (workflow_art in ('erstvertrag','verlaengerungsmitteilung'));
create unique index if not exists ux_wvdw_folgeentscheidung on public.wartungsvertrag_dokument_workflow(folgeentscheidung_id) where folgeentscheidung_id is not null;

alter table public.kommunikationsvorgang drop constraint if exists kommunikationsvorgang_vorgangstyp_check;
alter table public.kommunikationsvorgang add constraint kommunikationsvorgang_vorgangstyp_check check (vorgangstyp in ('vertrag_signatur','mail','druck','dokument_erzeugung'));
alter table public.kommunikationsvorgang drop constraint if exists kommunikationsvorgang_wvz_type_chk;
alter table public.kommunikationsvorgang add constraint kommunikationsvorgang_wvz_type_chk check (
  wartungsvertrag_zuordnung_id is null or (
    (vorgangstyp='vertrag_signatur' and dokumenttyp='wartungsvertrag') or
    (vorgangstyp='dokument_erzeugung' and dokumenttyp='wartungsvertrag_verlaengerung')
  )
);

-- This purpose is deliberately empty initially. It is assigned through the existing Vereinsfunktionsverwaltung.
create or replace function public.ist_wartungsvertrag_entscheidung_berechtigt(p_auth_user_id uuid default auth.uid(), p_stichtag date default current_date)
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select exists (
    select 1 from public.app_user au
    join public.vereinsfunktion_besetzung b on b.mitglied_id=au.mitglied_id and b.gueltig_ab<=p_stichtag and (b.gueltig_bis is null or b.gueltig_bis>=p_stichtag)
    join public.vereinsfunktion f on f.id=b.vereinsfunktion_id and f.aktiv
    join public.vereinsfunktion_verwendung v on v.vereinsfunktion_id=f.id and v.verwendungszweck='wartungsvertrag_entscheidung'
    where au.user_id=p_auth_user_id
  ) or exists (
    select 1 from public.app_user au
    join public.vereinsfunktion_besetzung eigene on eigene.mitglied_id=au.mitglied_id and eigene.gueltig_ab<=p_stichtag and (eigene.gueltig_bis is null or eigene.gueltig_bis>=p_stichtag)
    join public.vereinsfunktion_vertretung x on x.vertreter_besetzung_id=eigene.id and x.gueltig_ab<=p_stichtag and (x.gueltig_bis is null or x.gueltig_bis>=p_stichtag)
    join public.vereinsfunktion_besetzung vertretene on vertretene.id=x.vertretene_besetzung_id and vertretene.gueltig_ab<=p_stichtag and (vertretene.gueltig_bis is null or vertretene.gueltig_bis>=p_stichtag)
    join public.vereinsfunktion f on f.id=vertretene.vereinsfunktion_id and f.aktiv
    join public.vereinsfunktion_verwendung v on v.vereinsfunktion_id=f.id and v.verwendungszweck='wartungsvertrag_entscheidung'
    where au.user_id=p_auth_user_id
  );
$$;

create or replace function public.validate_wartungsvertrag_folgezuordnung()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_vorgaenger public.wartungsvertrag_zuordnungen%rowtype;
begin
  if new.vorgaenger_zuordnung_id is null then return new; end if;
  select * into v_vorgaenger from public.wartungsvertrag_zuordnungen where id=new.vorgaenger_zuordnung_id;
  if not found or v_vorgaenger.gueltig_bis is null then raise exception 'Die Vorgängerzuordnung muss ein festes Vertragsende besitzen.' using errcode='23514'; end if;
  if new.hauptmitglied_id is distinct from v_vorgaenger.hauptmitglied_id then raise exception 'Eine Folgezuordnung muss dasselbe Hauptmitglied besitzen.' using errcode='23514'; end if;
  if new.gueltig_ab <> v_vorgaenger.gueltig_bis + 1 then raise exception 'Eine Folgezuordnung muss am Tag nach dem Vertragsende beginnen.' using errcode='23514'; end if;
  return new;
end $$;
drop trigger if exists trg_validate_wartungsvertrag_folgezuordnung on public.wartungsvertrag_zuordnungen;
create trigger trg_validate_wartungsvertrag_folgezuordnung before insert or update of vorgaenger_zuordnung_id,hauptmitglied_id,gueltig_ab on public.wartungsvertrag_zuordnungen for each row execute function public.validate_wartungsvertrag_folgezuordnung();

create or replace function public.create_wartungsvertrag_dokument_workflow()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
  insert into public.wartungsvertrag_dokument_workflow(wartungsvertrag_zuordnung_id,workflow_art,status,fehlermeldung)
  values(new.id,case when new.vorgaenger_zuordnung_id is null then 'erstvertrag' else 'verlaengerungsmitteilung' end,'dokument_ausstehend',case when new.vorgaenger_zuordnung_id is null then 'Zuordnung gespeichert, Wartungsvertragsdokument noch nicht erzeugt: Es fehlt eine freigegebene Wartungsvertragsvorlage.' else null end)
  on conflict (wartungsvertrag_zuordnung_id) do nothing;
  return new;
end $$;

create or replace function public.validate_wartungsvertrag_kommunikationsvorgang_link()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_assignment public.wartungsvertrag_zuordnungen%rowtype;
begin
 if new.wartungsvertrag_zuordnung_id is null then return new; end if;
 select * into v_assignment from public.wartungsvertrag_zuordnungen where id=new.wartungsvertrag_zuordnung_id;
 if not found or new.mitglied_id is distinct from v_assignment.hauptmitglied_id or new.parzelle_id is not null then raise exception 'Der Wartungsvertragsvorgang passt nicht zur Zuordnung und ihrem Hauptmitglied.' using errcode='23514'; end if;
 if (new.vorgangstyp='vertrag_signatur' and new.dokumenttyp='wartungsvertrag' and v_assignment.vorgaenger_zuordnung_id is null)
    or (new.vorgangstyp='dokument_erzeugung' and new.dokumenttyp='wartungsvertrag_verlaengerung' and v_assignment.vorgaenger_zuordnung_id is not null) then return new; end if;
 raise exception 'Vorgangsart und Wartungsvertragszuordnung passen nicht zusammen.' using errcode='23514';
end $$;

create or replace function public.validate_wartungsvertrag_dokument_workflow()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_assignment public.wartungsvertrag_zuordnungen%rowtype; v_communication public.kommunikationsvorgang%rowtype; v_document public.dokument%rowtype;
begin
 select * into v_assignment from public.wartungsvertrag_zuordnungen where id=new.wartungsvertrag_zuordnung_id;
 if not found then raise exception 'Die Wartungsvertragszuordnung für den Dokumentvorgang wurde nicht gefunden.' using errcode='23503'; end if;
 if new.workflow_art='erstvertrag' and new.folgeentscheidung_id is not null then raise exception 'Ein Erstvertragsworkflow darf keine Folgeentscheidung referenzieren.' using errcode='23514'; end if;
 if new.workflow_art='verlaengerungsmitteilung' and v_assignment.vorgaenger_zuordnung_id is null then raise exception 'Eine Verlängerungsmitteilung benötigt eine Folgezuordnung.' using errcode='23514'; end if;
 if new.kommunikationsvorgang_id is not null and new.workflow_art='verlaengerungsmitteilung' and new.folgeentscheidung_id is null then raise exception 'Eine vorbereitete Verlängerungsmitteilung benötigt eine Folgeentscheidung.' using errcode='23514'; end if;
 if new.kommunikationsvorgang_id is not null then
   select * into v_communication from public.kommunikationsvorgang where id=new.kommunikationsvorgang_id;
   if not found or v_communication.wartungsvertrag_zuordnung_id is distinct from new.wartungsvertrag_zuordnung_id or v_communication.mitglied_id is distinct from v_assignment.hauptmitglied_id then raise exception 'Der Kommunikationsvorgang passt nicht zur Wartungsvertragszuordnung.' using errcode='23514'; end if;
   if (new.workflow_art='erstvertrag' and (v_communication.vorgangstyp<>'vertrag_signatur' or v_communication.dokumenttyp<>'wartungsvertrag')) or (new.workflow_art='verlaengerungsmitteilung' and (v_communication.vorgangstyp<>'dokument_erzeugung' or v_communication.dokumenttyp<>'wartungsvertrag_verlaengerung')) then raise exception 'Der Kommunikationsvorgang hat nicht die passende Workflow-Art.' using errcode='23514'; end if;
 end if;
 if new.dokument_id is not null then select * into v_document from public.dokument where id=new.dokument_id; if not found or v_document.mitglied_id is distinct from v_assignment.hauptmitglied_id then raise exception 'Das Dokument passt nicht zum Hauptmitglied.' using errcode='23514'; end if; end if;
 new.bearbeitet_am:=now(); return new;
end $$;

create or replace function public.guard_kommunikationsvorgang_update()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if tg_op='INSERT' then
   if new.vorgangstyp='vertrag_signatur' and new.status='vorbereitet' and new.zugewiesen_an is distinct from auth.uid() then raise exception 'Prepared contract must be assigned to its creating user' using errcode='42501'; end if;
   if auth.uid() is not null then new.erstellt_von:=auth.uid(); new.bearbeitet_von:=auth.uid(); end if;
   if new.signatur_gestartet_am is not null then new.signatur_gestartet_am:=now(); new.signatur_revision:=new.revision; elsif new.signatur_revision is not null then raise exception 'signatur_revision requires signatur_gestartet_am' using errcode='23514'; end if;
   return new;
 end if;
 if old.signatur_gestartet_am is not null and new.status<>'verworfen' and (new.signatur_gestartet_am is distinct from old.signatur_gestartet_am or new.signatur_revision is distinct from old.signatur_revision or new.entwurf_daten is distinct from old.entwurf_daten or new.revision is distinct from old.revision or new.dokumenttyp is distinct from old.dokumenttyp or new.mitglied_id is distinct from old.mitglied_id or new.parzelle_id is distinct from old.parzelle_id) then raise exception 'Signed communication workflow revision is immutable' using errcode='55000'; end if;
 if old.vorgangstyp='dokument_erzeugung' and (new.entwurf_daten is distinct from old.entwurf_daten or new.revision is distinct from old.revision or new.dokumenttyp is distinct from old.dokumenttyp or new.mitglied_id is distinct from old.mitglied_id or new.wartungsvertrag_zuordnung_id is distinct from old.wartungsvertrag_zuordnung_id) then raise exception 'Document-generation snapshot is immutable' using errcode='55000'; end if;
 if new.final_dokument_id is distinct from old.final_dokument_id and not ((old.status='zur_signatur' and new.status='letzte_pruefung' and old.final_dokument_id is null and new.final_dokument_id is not null) or (old.vorgangstyp='dokument_erzeugung' and old.status='vorbereitet' and new.status='erledigt' and old.final_dokument_id is null and new.final_dokument_id is not null)) then raise exception 'Final document may only be set by its workflow completion.' using errcode='55000'; end if;
 if new.status is distinct from old.status and not (
   (old.status='entwurf' and new.status in ('vorbereitet','abgebrochen')) or
   (old.status='vorbereitet' and new.status in ('entwurf','zur_signatur','abgebrochen','verworfen','erledigt')) or
   (old.status='zur_signatur' and new.status in ('vorbereitet','mail_bereit','druck_bereit','letzte_pruefung','abgebrochen','verworfen')) or
   (old.status='letzte_pruefung' and new.status in ('erledigt','verworfen')) or
   (old.status='mail_bereit' and new.status in ('wird_versendet','abgebrochen')) or
   (old.status='wird_versendet' and new.status in ('erledigt','fehler')) or
   (old.status='druck_bereit' and new.status in ('erledigt','fehler','abgebrochen')) or
   (old.status='fehler' and new.status in ('mail_bereit','druck_bereit','abgebrochen'))
 ) then raise exception 'Invalid communication workflow status transition: % -> %',old.status,new.status using errcode='23514'; end if;
 new.bearbeitet_am:=now(); if auth.uid() is not null then new.bearbeitet_von:=auth.uid(); end if; return new;
end $$;

-- Existing initial-contract RPC is intentionally fenced off from continuation assignments.
create or replace function public.ensure_wartungsvertrag_prepared_contract(p_zuordnung_id bigint)
returns public.kommunikationsvorgang language plpgsql security definer set search_path=public,pg_temp as $$
declare v_assignment public.wartungsvertrag_zuordnungen%rowtype; v_workflow public.wartungsvertrag_dokument_workflow%rowtype; v_contract public.kommunikationsvorgang%rowtype;
begin
  if not public.is_admin_or_vorstand() or auth.uid() is null then raise exception 'Nur administrative Vertragsbearbeitung darf Wartungsverträge vorbereiten.' using errcode='42501'; end if;
  select * into v_assignment from public.wartungsvertrag_zuordnungen where id=p_zuordnung_id;
  if not found then raise exception 'Die Wartungsvertragszuordnung wurde nicht gefunden.' using errcode='P0002'; end if;
  if v_assignment.vorgaenger_zuordnung_id is not null then raise exception 'Eine Verlängerungsmitteilung verwendet keinen Prepared-Signaturvorgang.' using errcode='23514'; end if;
  perform public.ensure_wartungsvertrag_dokument_workflow(p_zuordnung_id);
  select * into v_workflow from public.wartungsvertrag_dokument_workflow where wartungsvertrag_zuordnung_id=p_zuordnung_id for update;
  if v_workflow.workflow_art <> 'erstvertrag' then raise exception 'Der Dokumentworkflow ist kein Erstvertragsworkflow.' using errcode='23514'; end if;
  if v_workflow.kommunikationsvorgang_id is not null then select * into v_contract from public.kommunikationsvorgang where id=v_workflow.kommunikationsvorgang_id; return v_contract; end if;
  insert into public.kommunikationsvorgang(vorgangstyp,dokumenttyp,status,mitglied_id,wartungsvertrag_zuordnung_id,entwurf_daten,revision,zugewiesen_an)
  values('vertrag_signatur','wartungsvertrag','vorbereitet',v_assignment.hauptmitglied_id,v_assignment.id,jsonb_build_object('schema_version','kgv-prepared-contract/v1','document_type','wartungsvertrag','memberId',v_assignment.hauptmitglied_id,'wartungsvertrag_zuordnung_id',v_assignment.id,'wartungsvertrag_id',v_assignment.wartungsvertrag_id,'gueltig_ab',v_assignment.gueltig_ab::text,'gueltig_bis',v_assignment.gueltig_bis::text),1,auth.uid()) returning * into v_contract;
  update public.wartungsvertrag_dokument_workflow set kommunikationsvorgang_id=v_contract.id,status='dokument_ausstehend',fehlermeldung=null where id=v_workflow.id;
  return v_contract;
end $$;

create or replace function public.verlaengere_wartungsvertrag(p_vorgaenger_zuordnung_id bigint,p_wartungsvertrag_id bigint,p_neues_gueltig_bis date,p_vorstandsbeschlussdatum date,p_bemerkung text default null)
returns table(folgeentscheidung_id bigint,folgezuordnung_id bigint,kommunikationsvorgang_id bigint,workflow_id bigint)
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_alt public.wartungsvertrag_zuordnungen%rowtype; v_neu public.wartungsvertrag_zuordnungen%rowtype; v_dec public.wartungsvertrag_folgeentscheidung%rowtype; v_vorgang public.kommunikationsvorgang%rowtype; v_workflow public.wartungsvertrag_dokument_workflow%rowtype; v_member public.mitglied%rowtype; v_contract public.wartungsvertraege%rowtype;
begin
  if auth.uid() is null or not public.ist_wartungsvertrag_entscheidung_berechtigt() then raise exception 'Keine fachliche Berechtigung zur Wartungsvertragsentscheidung.' using errcode='42501'; end if;
  if p_vorstandsbeschlussdatum is null then raise exception 'Vorstandsbeschlussdatum ist erforderlich.' using errcode='22023'; end if;
  select * into v_alt from public.wartungsvertrag_zuordnungen where id=p_vorgaenger_zuordnung_id for update;
  if not found or v_alt.gueltig_bis is null then raise exception 'Die Zuordnung ist nicht regulär verlängerbar.' using errcode='23514'; end if;
  select * into v_dec from public.wartungsvertrag_folgeentscheidung where vorgaenger_zuordnung_id=v_alt.id and zurueckgenommen_am is null for update;
  if found then
    if v_dec.entscheidung='verlaengern' and v_dec.folgezuordnung_id is not null then select * into v_neu from public.wartungsvertrag_zuordnungen where id=v_dec.folgezuordnung_id; if v_neu.wartungsvertrag_id=p_wartungsvertrag_id and v_neu.gueltig_bis=p_neues_gueltig_bis and v_dec.vorstandsbeschlussdatum=p_vorstandsbeschlussdatum then select * into v_workflow from public.wartungsvertrag_dokument_workflow where folgeentscheidung_id=v_dec.id; return query select v_dec.id,v_neu.id,v_dec.kommunikationsvorgang_id,v_workflow.id; return; end if; end if;
    raise exception 'Für diese Laufzeit besteht bereits eine wirksame Folgeentscheidung.' using errcode='23514';
  end if;
  if exists(select 1 from public.wartungsvertrag_zuordnungen where vorgaenger_zuordnung_id=v_alt.id) then raise exception 'Für diese Laufzeit besteht bereits eine Folgezuordnung.' using errcode='23514'; end if;
  if p_neues_gueltig_bis < v_alt.gueltig_bis+1 then raise exception 'Das neue Vertragsende liegt vor dem serverseitig bestimmten Beginn.' using errcode='22023'; end if;
  select * into v_contract from public.wartungsvertraege where id=p_wartungsvertrag_id and aktiv=true for key share; if not found then raise exception 'Der Ziel-Wartungsvertrag fehlt oder ist nicht aktiv.' using errcode='23514'; end if;
  -- Insert intentionally runs the existing assignment trigger, including capacity and overlap protection.
  insert into public.wartungsvertrag_zuordnungen(wartungsvertrag_id,hauptmitglied_id,gueltig_ab,gueltig_bis,bemerkung,vorgaenger_zuordnung_id) values(p_wartungsvertrag_id,v_alt.hauptmitglied_id,v_alt.gueltig_bis+1,p_neues_gueltig_bis,nullif(btrim(p_bemerkung),''),v_alt.id) returning * into v_neu;
  insert into public.wartungsvertrag_folgeentscheidung(vorgaenger_zuordnung_id,entscheidung,entscheidungsdatum,entschieden_von_auth_user_id,vorstandsbeschlussdatum,folgezuordnung_id) values(v_alt.id,'verlaengern',p_vorstandsbeschlussdatum,auth.uid(),p_vorstandsbeschlussdatum,v_neu.id) returning * into v_dec;
  select * into v_member from public.mitglied where id=v_alt.hauptmitglied_id;
  insert into public.kommunikationsvorgang(vorgangstyp,dokumenttyp,status,mitglied_id,wartungsvertrag_zuordnung_id,entwurf_daten,revision,zugewiesen_an)
  values('dokument_erzeugung','wartungsvertrag_verlaengerung','vorbereitet',v_alt.hauptmitglied_id,v_neu.id,jsonb_build_object('schema_version','kgv-wartungsvertrag-verlaengerung/v1','template_key','wartungsvertrag-verlaengerung','template_version','v1','vorgaenger_zuordnung_id',v_alt.id,'folgezuordnung_id',v_neu.id,'folgeentscheidung_id',v_dec.id,'mitglied_id',v_alt.hauptmitglied_id,'mitglied_name',concat_ws(' ',v_member.vorname,v_member.name),'mitgliedsnummer',v_member.id,'wartungsvertrag_id',v_contract.id,'wartungsvertrag_titel',v_contract.titel,'wartungsvertrag_beschreibung',v_contract.beschreibung,'arbeitsstundenwirkung',case when v_contract.befreit_von_pflichtstunden then 'Befreiung von Pflichtstunden' else 'Keine Befreiung von Pflichtstunden' end,'vorgaenger_gueltig_bis',v_alt.gueltig_bis::text,'gueltig_ab',v_neu.gueltig_ab::text,'gueltig_bis',v_neu.gueltig_bis::text,'vorstandsbeschlussdatum',p_vorstandsbeschlussdatum::text,'bemerkung',p_bemerkung),1,auth.uid()) returning * into v_vorgang;
  update public.wartungsvertrag_folgeentscheidung set kommunikationsvorgang_id=v_vorgang.id where id=v_dec.id;
  update public.wartungsvertrag_dokument_workflow set workflow_art='verlaengerungsmitteilung',folgeentscheidung_id=v_dec.id,kommunikationsvorgang_id=v_vorgang.id,status='dokument_ausstehend',fehlermeldung=null where wartungsvertrag_zuordnung_id=v_neu.id returning * into v_workflow;
  return query select v_dec.id,v_neu.id,v_vorgang.id,v_workflow.id;
end $$;

create or replace function public.entscheide_wartungsvertrag_nichtverlaengerung(p_vorgaenger_zuordnung_id bigint,p_initiator text,p_entscheidungsdatum date,p_vorstandsbeschlussdatum date default null,p_begruendung text default null)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare v_alt public.wartungsvertrag_zuordnungen%rowtype; v_id bigint;
begin
 if auth.uid() is null or not public.ist_wartungsvertrag_entscheidung_berechtigt() then raise exception 'Keine fachliche Berechtigung zur Wartungsvertragsentscheidung.' using errcode='42501'; end if;
 if p_initiator not in ('verein','mitglied','beidseitig') or p_entscheidungsdatum is null then raise exception 'Initiator und Entscheidungsdatum sind erforderlich.' using errcode='22023'; end if;
 if p_initiator in ('verein','beidseitig') and p_vorstandsbeschlussdatum is null then raise exception 'Für Verein oder beidseitig ist ein Vorstandsbeschlussdatum erforderlich.' using errcode='22023'; end if;
 select * into v_alt from public.wartungsvertrag_zuordnungen where id=p_vorgaenger_zuordnung_id for update; if not found or v_alt.gueltig_bis is null then raise exception 'Die Zuordnung ist nicht regulär entscheidbar.' using errcode='23514'; end if;
 if exists(select 1 from public.wartungsvertrag_folgeentscheidung where vorgaenger_zuordnung_id=v_alt.id and zurueckgenommen_am is null) then raise exception 'Für diese Laufzeit besteht bereits eine wirksame Folgeentscheidung.' using errcode='23514'; end if;
 insert into public.wartungsvertrag_folgeentscheidung(vorgaenger_zuordnung_id,entscheidung,entscheidungsdatum,entschieden_von_auth_user_id,vorstandsbeschlussdatum,initiator,begruendung) values(v_alt.id,'nicht_verlaengern',p_entscheidungsdatum,auth.uid(),p_vorstandsbeschlussdatum,p_initiator,nullif(btrim(p_begruendung),'')) returning id into v_id;
 return v_id;
end $$;

create or replace function public.nehme_wartungsvertrag_nichtverlaengerung_zurueck(p_folgeentscheidung_id bigint,p_ruecknahmebegruendung text default null)
returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare v_dec public.wartungsvertrag_folgeentscheidung%rowtype; v_alt public.wartungsvertrag_zuordnungen%rowtype;
begin
 if auth.uid() is null or not public.ist_wartungsvertrag_entscheidung_berechtigt() then raise exception 'Keine fachliche Berechtigung zur Wartungsvertragsentscheidung.' using errcode='42501'; end if;
 select * into v_dec from public.wartungsvertrag_folgeentscheidung where id=p_folgeentscheidung_id for update; if not found or v_dec.entscheidung<>'nicht_verlaengern' or v_dec.zurueckgenommen_am is not null then raise exception 'Die Nichtverlängerung ist nicht rücknehmbar.' using errcode='23514'; end if;
 select * into v_alt from public.wartungsvertrag_zuordnungen where id=v_dec.vorgaenger_zuordnung_id for key share; if v_alt.gueltig_bis is null or current_date>=v_alt.gueltig_bis then raise exception 'Nach Vertragsende ist keine Rücknahme zulässig.' using errcode='23514'; end if;
 update public.wartungsvertrag_folgeentscheidung set zurueckgenommen_am=now(),zurueckgenommen_von_auth_user_id=auth.uid(),ruecknahmebegruendung=nullif(btrim(p_ruecknahmebegruendung),'') where id=v_dec.id;
 return v_dec.id;
end $$;

create or replace function public.validate_wartungsvertrag_folgeentscheidung()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_alt public.wartungsvertrag_zuordnungen%rowtype; v_folge public.wartungsvertrag_zuordnungen%rowtype;
begin
 select * into v_alt from public.wartungsvertrag_zuordnungen where id=new.vorgaenger_zuordnung_id;
 if not found or v_alt.gueltig_bis is null then raise exception 'Die Folgeentscheidung benötigt eine auslaufende Vorgängerzuordnung.' using errcode='23514'; end if;
 if new.entscheidung='verlaengern' then
   select * into v_folge from public.wartungsvertrag_zuordnungen where id=new.folgezuordnung_id;
   if not found or v_folge.vorgaenger_zuordnung_id is distinct from v_alt.id then raise exception 'Die Folgezuordnung passt nicht zur Vorgängerzuordnung.' using errcode='23514'; end if;
 end if;
 new.updated_at:=now(); return new;
end $$;
drop trigger if exists trg_validate_wartungsvertrag_folgeentscheidung on public.wartungsvertrag_folgeentscheidung;
create trigger trg_validate_wartungsvertrag_folgeentscheidung before insert or update on public.wartungsvertrag_folgeentscheidung for each row execute function public.validate_wartungsvertrag_folgeentscheidung();

create or replace function public.get_auslaufende_wartungsvertrag_zuordnungen()
returns table(zuordnung_id bigint,hauptmitglied_id bigint,mitglied_name text,wartungsvertrag_id bigint,wartungsvertrag_titel text,gueltig_ab date,gueltig_bis date,entscheidung text,folgeentscheidung_id bigint,folgezuordnung_id bigint,zurueckgenommen_am timestamptz,can_decide boolean)
language sql stable security definer set search_path=public,pg_temp as $$
 select z.id,z.hauptmitglied_id,nullif(btrim(concat_ws(' ',m.vorname,m.name)),''),z.wartungsvertrag_id,w.titel,z.gueltig_ab,z.gueltig_bis,e.entscheidung,e.id,e.folgezuordnung_id,e.zurueckgenommen_am,(public.ist_wartungsvertrag_entscheidung_berechtigt() and z.gueltig_bis>current_date and (e.id is null or e.zurueckgenommen_am is not null))
 from public.wartungsvertrag_zuordnungen z
 join public.mitglied m on m.id=z.hauptmitglied_id
 join public.wartungsvertraege w on w.id=z.wartungsvertrag_id
 left join lateral (select * from public.wartungsvertrag_folgeentscheidung x where x.vorgaenger_zuordnung_id=z.id order by x.created_at desc limit 1) e on true
 where z.gueltig_bis is not null and z.gueltig_bis>=current_date
   and not exists(select 1 from public.wartungsvertrag_zuordnungen f where f.vorgaenger_zuordnung_id=z.id)
 order by z.gueltig_bis asc,z.id asc;
$$;

create or replace function public.get_wartungsvertrag_folgeentscheidung_detail(p_vorgaenger_zuordnung_id bigint)
returns table(vorgaenger_zuordnung_id bigint,hauptmitglied_id bigint,wartungsvertrag_id bigint,gueltig_ab date,gueltig_bis date,folgeentscheidung_id bigint,entscheidung text,entscheidungsdatum date,vorstandsbeschlussdatum date,initiator text,begruendung text,folgezuordnung_id bigint,folge_wartungsvertrag_id bigint,folge_wartungsvertrag_titel text,folge_gueltig_ab date,folge_gueltig_bis date,kommunikationsvorgang_id bigint,workflow_id bigint,workflow_art text,workflow_status text,dokument_id bigint,zurueckgenommen_am timestamptz,ruecknahmebegruendung text,can_decide boolean,can_withdraw_nichtverlaengerung boolean)
language sql stable security definer set search_path=public,pg_temp as $$
 select z.id,z.hauptmitglied_id,z.wartungsvertrag_id,z.gueltig_ab,z.gueltig_bis,e.id,e.entscheidung,e.entscheidungsdatum,e.vorstandsbeschlussdatum,e.initiator,e.begruendung,e.folgezuordnung_id,f.wartungsvertrag_id,fw.titel,f.gueltig_ab,f.gueltig_bis,e.kommunikationsvorgang_id,wd.id,wd.workflow_art,wd.status,wd.dokument_id,e.zurueckgenommen_am,e.ruecknahmebegruendung,(public.ist_wartungsvertrag_entscheidung_berechtigt() and z.gueltig_bis>current_date and (e.id is null or e.zurueckgenommen_am is not null)),(public.ist_wartungsvertrag_entscheidung_berechtigt() and e.entscheidung='nicht_verlaengern' and e.zurueckgenommen_am is null and z.gueltig_bis>current_date)
 from public.wartungsvertrag_zuordnungen z
 left join public.wartungsvertrag_folgeentscheidung e on e.vorgaenger_zuordnung_id=z.id
 left join public.wartungsvertrag_zuordnungen f on f.id=e.folgezuordnung_id
 left join public.wartungsvertraege fw on fw.id=f.wartungsvertrag_id
 left join public.wartungsvertrag_dokument_workflow wd on wd.folgeentscheidung_id=e.id
 where z.id=p_vorgaenger_zuordnung_id;
$$;

-- Neutral document workflows may set a final document without entering a signature state.
create or replace function public.complete_wartungsvertrag_verlaengerungsmitteilung(p_kommunikationsvorgang_id bigint,p_dokument_id bigint)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if auth.uid() is null and auth.role() is distinct from 'service_role' then raise exception 'Anmeldung erforderlich.' using errcode='42501'; end if;
 update public.kommunikationsvorgang set final_dokument_id=p_dokument_id,status='erledigt' where id=p_kommunikationsvorgang_id and vorgangstyp='dokument_erzeugung' and dokumenttyp='wartungsvertrag_verlaengerung' and status='vorbereitet';
 if not found then raise exception 'Verlängerungsmitteilung ist nicht abschließbar.' using errcode='40001'; end if;
 update public.wartungsvertrag_dokument_workflow set dokument_id=p_dokument_id,status='abgeschlossen',fehlermeldung=null where kommunikationsvorgang_id=p_kommunikationsvorgang_id and workflow_art='verlaengerungsmitteilung';
end $$;

